MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M t USING (SELECT 'AS_FROM_SITE' AS SQL_ID, 'DM' AS MDU_DIVS_CD, '[B] AS-IS @Code=''AS_FROM_SITE'' 수작업 통합 변환 — IF분기 통합(param1 빈값=전체)' AS SQL_NM, 'SELECT SEGMENT2 AS CODE, SEGMENT1 AS NAME FROM SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE = ''AS_SITE_PLANT'' AND VALID_YN = ''Y'' AND (NVL(TRIM(@param1), ''-'') = ''-'' OR SEGMENT3 = @param1) ORDER BY DISPLAY_SEQ' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'minyonglee1' AS CREATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'minyonglee1' AS LAST_UPDATED_BY, TO_DATE('2026-07-02 23:24:25','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
ON (t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD)
