MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M t USING (SELECT 'EndCustomer' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'EndCustomer' AS SQL_NM, 'SELECT DISTINCT A.DIVISION_ID, B.DEPT_ID,        CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE             ELSE A.END_CUSTOMER        END AS CODE,        NVL(D.SEGMENT3, CASE WHEN A.DIVISION_ID = ''40'' THEN B.PROJECT_CODE                             ELSE A.END_CUSTOMER                        END) AS NAME FROM SCM_MGR.SCM_MST_SITE A LEFT OUTER JOIN SCM_MGR.SCM_MST_SITE_ITEM B              ON A.DIVISION_ID = B.DIVISION_ID             AND A.SCM_SITE_ID = B.SCM_SITE_ID LEFT OUTER JOIN SCM_MGR.SCM_ADM_LOOKUP_MASTER_DETAIL D              ON A.DIVISION_ID = D.SEGMENT1             AND A.END_CUSTOMER = D.SEGMENT2             AND D.LOOKUP_TYPE = ''END_CUSTOMER''             AND D.VALID_YN = ''Y'' WHERE A.DIVISION_ID IN (     SELECT DISTINCT UNIT_ID AS DIVISION_ID     FROM SCM_MGR.SCM_ADM_USER_GR_UNIT_AUTH_MPG_M     WHERE USER_ID = @sesUserId       AND UNIT_TP_CD = ''D'' ) AND A.END_CUSTOMER IS NOT NULL ORDER BY DIVISION_ID, DEPT_ID, CODE' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-13 12:05:25','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
ON (t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET t.SQL_NM = s.SQL_NM, t.SQL_DTL_CTN = s.SQL_DTL_CTN, t.USE_YN = s.USE_YN, t.CREATED_BY = s.CREATED_BY, t.CREATION_DATE = s.CREATION_DATE, t.LAST_UPDATED_BY = s.LAST_UPDATED_BY, t.LAST_UPDATE_DATE = s.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE);
MERGE INTO SCM_MGR.SCM_ADM_CMBO_SQL_M t USING (SELECT 'EndCustomerByDivisionDept' AS SQL_ID, 'DM' AS MDU_DIVS_CD, 'End Customer by division, team' AS SQL_NM, 'SELECT DISTINCT 	A.DIVISION_ID AS DIVISION_ID,     A.END_CUSTOMER AS CODE,     NVL(D.SEGMENT3, A.END_CUSTOMER) AS NAME FROM ( 	SELECT DISTINCT 	     site.DIVISION_ID 	   , site.END_CUSTOMER 	   , item.DEPT_ID, item.PROJECT_CODE 	   , site.SCM_SITE_ID AS CODE 	   , site.SCM_SITE_ID AS NAME 	FROM      SCM_MST_SITE site 	LEFT JOIN SCM_MST_SITE_ITEM item 	       ON site.DIVISION_ID = item.DIVISION_ID 	      AND site.SCM_SITE_ID = item.SCM_SITE_ID ) A LEFT OUTER JOIN SCM_ADM_LOOKUP_MASTER_DETAIL D     ON A.DIVISION_ID = D.SEGMENT1    AND A.END_CUSTOMER = D.SEGMENT2    AND D.LOOKUP_TYPE = ''END_CUSTOMER''    AND D.VALID_YN = ''Y'' WHERE 1 = 1 --  AND ( --        (@divisionId = NULL OR @divisionId = ''ALL'' OR @divisionId = '''') --        OR A.DIVISION_ID IN ( --            SELECT REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@divisionId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND ( --        (@deptId = NULL OR @deptId = ''ALL'' OR @deptId = '''') --        OR A.DEPT_ID IN ( --            SELECT REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) --            FROM DUAL --            CONNECT BY REGEXP_SUBSTR(@deptId, ''[^,]+'', 1, LEVEL) IS NOT NULL --        ) --      ) --  AND A.DIVISION_ID IN ( --        SELECT DISTINCT UNIT_ID --        FROM SCM_ADM_USER_GR_UNIT_AUTH_MPG_M --        WHERE USER_ID = @sesUserId --          AND UNIT_TP_CD = ''D'' --      )   AND A.DIVISION_ID IS NOT NULL   AND A.DEPT_ID IS NOT NULL   AND A.END_CUSTOMER IS NOT NULL ORDER BY A.END_CUSTOMER' AS SQL_DTL_CTN, 'Y' AS USE_YN, 'SYSTEM' AS CREATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS CREATION_DATE, 'SYSTEM' AS LAST_UPDATED_BY, TO_DATE('2026-02-20 15:50:53','YYYY-MM-DD HH24:MI:SS') AS LAST_UPDATE_DATE FROM DUAL) s
ON (t.SQL_ID = s.SQL_ID AND t.MDU_DIVS_CD = s.MDU_DIVS_CD)
WHEN MATCHED THEN UPDATE SET t.SQL_NM = s.SQL_NM, t.SQL_DTL_CTN = s.SQL_DTL_CTN, t.USE_YN = s.USE_YN, t.CREATED_BY = s.CREATED_BY, t.CREATION_DATE = s.CREATION_DATE, t.LAST_UPDATED_BY = s.LAST_UPDATED_BY, t.LAST_UPDATE_DATE = s.LAST_UPDATE_DATE
WHEN NOT MATCHED THEN INSERT (SQL_ID, MDU_DIVS_CD, SQL_NM, SQL_DTL_CTN, USE_YN, CREATED_BY, CREATION_DATE, LAST_UPDATED_BY, LAST_UPDATE_DATE) VALUES (s.SQL_ID, s.MDU_DIVS_CD, s.SQL_NM, s.SQL_DTL_CTN, s.USE_YN, s.CREATED_BY, s.CREATION_DATE, s.LAST_UPDATED_BY, s.LAST_UPDATE_DATE);
